#!/usr/bin/env node
/**
 * Dendrynexus tabbed-sidebar builds update out/game.json but leave a vendored
 * out/html/core.js whose window.game={compiled:'…'} block goes stale. The game
 * actually runs from that embed, so the build-stamp footer can lag by hours.
 *
 * After make-html, copy fresh out/game.json into the core.js prefix.
 */

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const CORE = path.join(ROOT, 'out', 'html', 'core.js')
const GAME_JSON = path.join(ROOT, 'out', 'game.json')
const PREFIX = "window.game={compiled:'"
const BUNDLE_MARKER = "'},function e(t,n,i){"

function escapeForJsSingleQuoted(s) {
  return s
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\r/g, '\\r')
    .replace(/\n/g, '\\n')
}

function sync() {
  if (!fs.existsSync(CORE)) {
    console.error('sync-core-embedded-game: missing', CORE)
    process.exit(1)
  }
  if (!fs.existsSync(GAME_JSON)) {
    console.error('sync-core-embedded-game: missing', GAME_JSON)
    process.exit(1)
  }

  const core = fs.readFileSync(CORE, 'utf8')
  if (!core.startsWith(PREFIX)) {
    console.error('sync-core-embedded-game: unexpected core.js layout (no', PREFIX, ')')
    process.exit(1)
  }

  const markerAt = core.indexOf(BUNDLE_MARKER)
  if (markerAt === -1) {
    console.error('sync-core-embedded-game: bundle marker not found in core.js')
    process.exit(1)
  }

  const game = fs.readFileSync(GAME_JSON, 'utf8')
  const next = PREFIX + escapeForJsSingleQuoted(game) + core.slice(markerAt)

  if (next === core) {
    return
  }

  fs.writeFileSync(CORE, next)
  const m = game.match(/build_time_label = '([^']+)'/)
  console.log(
    'sync-core-embedded-game: refreshed embedded game in out/html/core.js'
    + (m ? ` (stamp ${m[1]})` : '')
  )
}

sync()

module.exports = { sync, PREFIX, BUNDLE_MARKER, escapeForJsSingleQuoted }

#!/usr/bin/env node
/**
 * Embed build time into source, compile HTML, write out/html/build-stamp.txt.
 *
 * Usage:
 *   node scripts/make-html.js
 *   node scripts/make-html.js --force
 *   npm run make-html -- --force
 */

const { execSync } = require('child_process')
const path = require('path')

const ROOT = path.join(__dirname, '..')

require('./write-build-stamp.js').embedBuildStamp()

const extra = process.argv.slice(2).filter((a) => a !== '--')
const force = extra.includes('--force')
const template = path.join('templates', 'html', 'default-tabbed-sidebar')
const cmd = [
  'npx', 'dendrynexus', 'make-html', '--pretty',
  '-t', template,
  '--overwrite',
  ...(force ? ['--force'] : []),
]

console.log('running:', cmd.join(' '))
execSync(cmd.join(' '), { cwd: ROOT, stdio: 'inherit' })

const htmlDir = path.join(ROOT, 'out', 'html')
const gameJson = path.join(ROOT, 'out', 'game.json')
if (require('fs').existsSync(gameJson)) {
  require('fs').copyFileSync(gameJson, path.join(htmlDir, 'game.json'))
}

require('./sync-core-embedded-game.js')

require('./write-build-stamp.js').writeStampFile()

require('./inject-dev-cache-meta.js')

