const DEMO_APPEALS = {
    rich: [0, 0, 0, 6, 1, 0, 2],
    first: [1, 2, 0, 1, -3, 0, 5],
    second: [2, 1, 0, 0, 2, 0, 6],
    coop: [2, 0, 20, -3, -3, 0, 6],
    drone: [3, 0, 0, 3, 2, 0, 2],
    alien: [2, 0, 0, -6, -3, 0, 9],
    deeper: [2, 36, -5, 2, -2, 0, 6],
}

function buildDemographics() {
    return STRATUM_IDS.map((id) => {
        const configs = {
