// Election v2 — IG floor + competitive softmax. Keep in sync with source/lib/election-v2.js
// CLI: npm run simulate-election:v2

(function initMikasaElectionV2() {

const VOTE_TO_PARTY = { Dems: "D", Ind: "I", Corp: "C", Gang: "G", Hate: "H" }

const PARTY_KEYS = ['D', 'I', 'C', 'G', 'H']
const PARTY_LABELS = {
    D: 'Dems',
    I: 'Ind',
    C: 'Corp',
    G: 'Gang',
    H: 'Hate',
}

const STRATUM_IDS = ['rich', 'first', 'second', 'coop', 'drone', 'alien', 'deeper']

const STRATUM_DISPLAY = {
    rich: 'Rich',
    first: 'First',
    second: 'Second',
    coop: 'Clans',
    drone: 'Corp Drone',
    alien: 'Otherworlder',
    deeper: 'Deepers',
}

const DISTRICT_IDS = [
    'Docks', 'Aurora', 'Vats', 'Railyard', 'Pitts', 'Limelight', 'Deeps',
]

const DISTRICT_DISPLAY = {
    Docks: 'District 1 (The Docks)',
    Aurora: 'District 2 (Aurora District)',
    Vats: 'District 3 (The Vats)',
    Railyard: 'District 4 (The Railyard)',
    Pitts: 'District 5 (The Pitts)',
    Limelight: 'District 6 (The Limelight)',
    Deeps: 'District 7 (The Deeps)',
}

/** Home-district multiplier for IG membership share in that district. */
const DISTRICT_IG_BOOST = {
    Soylent: { Vats: 1.4, Railyard: 1.25, Docks: 1.1 },
    Magrail: { Railyard: 1.35, Docks: 1.3, Aurora: 1.1 },
    Brazos: { Limelight: 1.4, Vats: 1.15, Pitts: 1.1 },
    Families: { Pitts: 1.5, Aurora: 1.2, Docks: 1.15 },
    Edges: { Aurora: 1.35, Railyard: 1.2, Limelight: 1.15 },
    Sharks: { Pitts: 1.6, Limelight: 1.2, Deeps: 1.1 },
}

const EXEC_SEATS = 150
const GUILD_SEATS = 35
const DISTRICT_SEATS = 15
const VOTE_SCALE = 10000
const EXEC_ELECTION_MONTH = 12
const GUILD_KEYS = ['Gold', 'White', 'Blue']

/** District council election month (1–12). Order: Docks … Deeps. */
const DISTRICT_ELECTION_MONTH = {
    Docks: 6,
    Aurora: 4,
    Vats: 2,
    Railyard: 11,
    Pitts: 5,
    Limelight: 6,
    Deeps: 8,
}

/** Starting prosperity for every voter block in the district (1.0 = Mikasa average). */
const DISTRICT_STARTING_PROSPERITY = {
    Docks: 1.5,
    Pitts: 0.5,
}

// --- utilities ----------------------------------------------------------------

const sum = (nums) => nums.reduce((a, b) => a + b, 0)

const zeroPartyVotes = () => ({ D: 0, I: 0, C: 0, G: 0, H: 0 })

function assign_percentages(rawByParty, nSeats) {
    const raw = PARTY_KEYS.map((k) => rawByParty[k] || 0)
    const total = sum(raw)
    if (total === 0 || nSeats === 0) {
        return Object.fromEntries(PARTY_KEYS.map((k) => [k, 0]))
    }
    const votesPerSeat = total / nSeats
    const remainders = raw.map((v) => v % votesPerSeat)
    const whole = raw.map((v, i) => (v - remainders[i]) / votesPerSeat)
    let unassigned = nSeats - sum(whole.map(Math.floor))
    const rem = remainders.slice()
    for (let i = 0; i < unassigned; i++) {
        const idx = rem.reduce((best, x, j, arr) => (x > arr[best] ? j : best), 0)
        whole[idx] += 1
        rem[idx] = 0
    }
    return Object.fromEntries(PARTY_KEYS.map((k, i) => [k, Math.round(whole[i])]))
}

function formatSeatChange(delta) {
    if (delta > 0) { return '+' + delta }
    if (delta < 0) { return String(delta) }
    return '0'
}

/** Expose district election results as Q qualities for [+ … +] in scene prose (see scheduled_elections). */
function publishDistrictElectionReport(did, votes, oldSeats, newSeats) {
    const pct = votesToPollPercents(votes || zeroPartyVotes())
    Q['election_show_' + did] = 1
    for (const k of PARTY_KEYS) {
        Q[did + '_ev_' + k + '_pct'] = pct[k]
        Q[did + '_ev_' + k + '_seats'] = newSeats[k] || 0
        Q[did + '_ev_' + k + '_chg'] = formatSeatChange(
            (newSeats[k] || 0) - (oldSeats[k] || 0)
        )
    }
}

/** One-quarter guild turnover: 3 parts held seats, 1 part current poll (largest remainder). */
function rotateGuildSeatsQuarter(currentSeats, pollVotes, nSeats) {
    const rotate = Math.ceil(nSeats / 4)
    const keep = nSeats - rotate
    const mass = zeroPartyVotes()
    for (const k of PARTY_KEYS) {
        mass[k] = (currentSeats[k] || 0) * keep + (pollVotes[k] || 0) * rotate
    }
    return assign_percentages(mass, nSeats)
}

function softmax(scores, temperature = 1) {
    const keys = PARTY_KEYS
    const exps = keys.map((k) => Math.exp((scores[k] || 0) / temperature))
    const total = sum(exps) || 1
    return Object.fromEntries(keys.map((k, i) => [k, exps[i] / total]))
}

/** Legacy vote-label appeals (Dems, Corp, …) → competitive logit scale. */
const APPEAL_TO_SCORE = 0.05

function applyAppealsTo(target, labels, values) {
    for (let i = 0; i < labels.length; i++) {
        target[labels[i]] = values[i] || 0
    }
}

function voteLabelAppealsToScores(entity) {
    const scores = zeroPartyVotes()
    for (const [label, party] of Object.entries(VOTE_TO_PARTY)) {
        scores[party] = (entity[label] || 0) * APPEAL_TO_SCORE
    }
    return scores
}

function syncVoteAppealsToCompetitive(entity) {
    const base = entity._baseCompetitiveScores || zeroPartyVotes()
    const fromAppeals = voteLabelAppealsToScores(entity)
    entity.competitiveScores = {}
    for (const k of PARTY_KEYS) {
        entity.competitiveScores[k] = (base[k] || 0) + (fromAppeals[k] || 0)
    }
}

function syncGlobalVoteAppeals(state, labels, shifts) {
    const base = state._baseGlobalScores || zeroPartyVotes()
    const row = Object.fromEntries(labels.map((l, i) => [l, shifts[i] || 0]))
    const fromAppeals = voteLabelAppealsToScores(row)
    state.global.competitiveScores = {}
    for (const k of PARTY_KEYS) {
        state.global.competitiveScores[k] = (base[k] || 0) + (fromAppeals[k] || 0)
    }
}

function syncAllVoteAppeals(stratums, state, labels, globalShifts) {
    for (const s of stratums) {
        syncVoteAppealsToCompetitive(s)
    }
    if (state) {
        syncGlobalVoteAppeals(state, labels, globalShifts)
    }
}

// --- VoterBlock: demographic × district only ----------------------------------

class VoterBlock {
    constructor(demographic, district, population) {
        this.demographic = demographic
        this.district = district
        this.population = population
        /** Local economic prosperity (1.0 = baseline; cards/ticks may adjust). */
        this.prosperity = district.startingProsperity ?? 1
        /** Competitive party scores (events modify these). */
        this.competitiveScores = { D: 0, I: 0, C: 0, G: 0, H: 0 }
        /** Fringe=low steepness, mainstream=high. */
        this.competitiveSteepness = { D: 1, I: 1, C: 1, G: 1, H: 1 }
        demographic.blocks.push(this)
        district.blocks.push(this)
    }

    get id() {
        return `${this.district.id}_${this.demographic.id}`
    }
}

class Demographic {
    constructor(id, config, appeals) {
        this.id = id
        this.blocks = []
        this.competitiveScores = Object.assign(
            { D: 0, I: 0, C: 0, G: 0, H: 0 },
            config.competitiveScores || {}
        )
        this.competitiveSteepness = Object.assign(
            { D: 1, I: 1, C: 1, G: 1, H: 1 },
            config.competitiveSteepness || {}
        )
        this._baseCompetitiveScores = Object.assign({}, this.competitiveScores)
        /** Max share of this stratum claimed by all IGs combined (rest = competitive). */
        this.igClaimCap = config.igClaimCap ?? 0.5
        this.executiveWeight = config.executiveWeight ?? 1
        /** Optional BLOCK_VOTE_RULES key, e.g. 'corp_or_abstain' for drones. */
        this.voteRule = config.voteRule || null
        if (appeals) {
            applyAppealsTo(this, Q.vote_labels, appeals)
            syncVoteAppealsToCompetitive(this)
        }
        this.name = this.id
        Q.stratums.push(this)
        Q.lookups[this.id] = this
        Q[this.id] = this
    }
}

class District {
    constructor(id, populations, config) {
        this.id = id
        this.blocks = []
        this.populations = populations
        this.competitiveScores = Object.assign(
            { D: 0, I: 0, C: 0, G: 0, H: 0 },
            config.competitiveScores || {}
        )
        this._baseCompetitiveScores = Object.assign({}, this.competitiveScores)
        this.competitiveTurnoutBonus = config.competitiveTurnoutBonus ?? 0
        this.lowTurnoutGangBonus = config.lowTurnoutGangBonus ?? 0
        this.electionMonth = config.electionMonth ?? 1
        this.startingProsperity =
            config.startingProsperity ?? DISTRICT_STARTING_PROSPERITY[id] ?? 1
        this.name = this.id
        for (let i = 0; i < Q.stratum_labels.length; i++) {
            this[Q.stratum_labels[i]] = populations[i] || 0
        }
        Q.regions.push(this)
        Q.lookups[this.id] = this
        Q[this.id] = this
    }
}

/**
 * Interest group: claims a fraction of each stratum and votes with a fixed party mix.
 * @param {object} config
 * @param {'corporate'|'syndicate'|'guild'} config.kind
 * @param {number[]} config.membership - per-stratum share (of entire stratum) in this IG
 * @param {object} config.partyShares - D,I,C,G,H summing ~1
 */
class InterestGroup {
    constructor(id, config) {
        this.id = id
        this.kind = config.kind
        this.membership = config.membership || STRATUM_IDS.map(() => 0)
        this.partyShares = normalizeShares(config.partyShares || { C: 1 })
        this.turnout = config.turnout ?? 0.9
        this.guildSeatKey = config.guildSeatKey || null
    }

    /** Effective membership in a block (national share × district home boost, capped). */
    effectiveMembership(block) {
        const idx = STRATUM_IDS.indexOf(block.demographic.id)
        const base = this.membership[idx] || 0
        const boost = (DISTRICT_IG_BOOST[this.id] || {})[block.district.id] || 1
        return base * boost
    }
}

function normalizeShares(shares) {
    const total = sum(PARTY_KEYS.map((k) => shares[k] || 0)) || 1
    return Object.fromEntries(PARTY_KEYS.map((k) => [k, (shares[k] || 0) / total]))
}

// --- chamber config -----------------------------------------------------------

const CHAMBERS = {
    executive: {
        seats: EXEC_SEATS,
        prefix: 'Exec',
        elects: 'global',
        igKinds: ['corporate', 'syndicate', 'guild'],
        igTurnoutMult: 1,
        competitiveTurnout: 0.35,
        useExecutiveWeight: true,
    },
    guild: {
        seats: GUILD_SEATS,
        elects: 'perGuild',
        igKinds: ['guild'],
        igTurnoutMult: 1.1,
        competitiveTurnout: 0.05,
        useExecutiveWeight: false,
    },
    district: {
        seats: DISTRICT_SEATS,
        elects: 'perDistrict',
        igKinds: ['corporate', 'syndicate'],
        igTurnoutMult: 0.85,
        competitiveTurnout: 0.4,
        useExecutiveWeight: false,
    },
}

// --- world bootstrap ----------------------------------------------------------

function buildInterestGroups() {
    const z = () => STRATUM_IDS.map(() => 0)

    return [
        // Corporate shareholder blocs (→ Corp)
        new InterestGroup('Soylent', {
            kind: 'corporate',
            membership: [0.08, 0.02, 0.01, 0, 0.22, 0, 0],
            partyShares: { C: 0.92, I: 0.05, D: 0.02, G: 0, H: 0.01 },
            turnout: 0.95,
        }),
        new InterestGroup('Magrail', {
            kind: 'corporate',
            membership: [0.06, 0.02, 0.01, 0, 0.18, 0, 0],
            partyShares: { C: 0.9, I: 0.06, D: 0.03, G: 0, H: 0.01 },
            turnout: 0.93,
        }),
        new InterestGroup('Brazos', {
            kind: 'corporate',
            membership: [0.07, 0.02, 0.02, 0, 0.15, 0, 0],
            partyShares: { C: 0.88, I: 0.07, D: 0.03, G: 0.01, H: 0.01 },
