        }),

        // Guild blocs (guild chamber; also add executive floor)
        new InterestGroup('Executive', {
            kind: 'guild',
            membership: [0.35, 0.01, 0, 0, 0.02, 0, 0],
            partyShares: { C: 0.75, I: 0.1, D: 0.05, G: 0.05, H: 0.05 },
