                executiveWeight: 0.8,
                competitiveScores: { D: 1.5, I: 1, C: -1, G: -0.5, H: -0.5 },
            },
        }
        return new Demographic(id, configs[id] || {})
    })
}

function buildDistricts() {
    const pops = [
        [17, 42, 30, 1, 11, 1, 1],
        [0, 58, 57, 1, 2, 9, 3],
        [1, 8, 11, 1, 48, 0, 1],
        [0, 12, 10, 1, 52, 0, 1],
